head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        MxTab_1.setSelectedTabIndex(1);

        // 오늘날짜로 초기화시킨다.
        const y_day = $c.ud.fn_get_search_taskdd(dts_TASK_DD, 'I');
        edt_base_dt_1.setValue(y_day);

        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35607.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35607.dts_List_1_OnLoadCompleted" });
    }
};

