/**
 * @method
 * @name btn_base_dt_1_onclick
 * @description btn_base_dt_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_base_dt_1_onclick = function() {
    try {
        popUpCalendar2(edt_base_dt_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35607.btn_base_dt_1_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        const tIndex = MxTab_1.getSelectedTabIndex();
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35607.xml", SCREN_PROCS_TP_CD_07);
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        const xls_path = $c.session.getExcelDownPath() + today + "상장폐지-시가총액우려예고(유)_STF35607.xls";
        if (tIndex === 1) {
            if (dts_List_1.getRowCount() > 0 && dts_List_2.getRowCount() > 0) {
                $c.data.saveExcel(grd_List_1, "관리종목지정(시가총액 요건 미달) 우려 예고법인", false, false, false, xls_path);
                $c.data.downloadGridViewExcel(grd_List_2, {fileName: "관리종목(시가총액 요건 미달)", sheetName: xls_path, type: 40});
            } else {
                if (dts_List_1.getRowCount() > 0) {
                    $c.data.downloadGridViewExcel(grd_List_1, {fileName: "관리종목지정(시가총액 요건 미달) 우려 예고법인", type: 8});
                }
                if (dts_List_2.getRowCount() > 0) {
                    $c.data.downloadGridViewExcel(grd_List_2, {fileName: "관리종목(시가총액 요건 미달)", type: 8});
                }
            }
        } else if (tIndex === 2) {
            if (dts_List_3.getRowCount() > 0 && dts_List_4.getRowCount() > 0) {
                $c.data.saveExcel(grd_List_3, "종류주식 관리종목지정(시가총액 요건 미달) 우려 예고법인", false, false, false, xls_path);
                $c.data.downloadGridViewExcel(grd_List_4, {fileName: "종류주식 관리종목(시가총액 요건 미달)", sheetName: xls_path, type: 40});
            } else {
                if (dts_List_3.getRowCount() > 0) {
                    $c.data.downloadGridViewExcel(grd_List_3, {fileName: "종류주식 관리종목지정(시가총액 요건 미달) 우려 예고법인", type: 8});
                }
                if (dts_List_4.getRowCount() > 0) {
                    $c.data.downloadGridViewExcel(grd_List_4, {fileName: "종류주식 관리종목(시가총액 요건 미달)", type: 8});
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35607.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35607.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35607.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 관리종목 관련정보  검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let baseDt = edt_base_dt_1.GetSelClipText(0, 8);
    if ("" !== baseDt) {
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/AdminAndDlstedDetection.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_List_2",
            action : "/AdminAndDlstedDetection.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        await $c.win.alert("기준일자를 입력하세요");
    }
};

